'use client';

import * as React from 'react';
import {createComponent} from '@lit/react';
import '@material/web/labs/gb/components/fab/md-gb-fab.js';
import {FabElement} from '@material/web/labs/gb/components/fab/fab-element.js';

/**
 * A Material Design component. Wraps <md-gb-fab>.
 * Docs: https://material-web.dev/3.0/components/fab/
 */
export const MdFab = createComponent({
  react: React,
  tagName: 'md-gb-fab',
  elementClass: FabElement,
});

export type MdFabProps = React.ComponentProps<typeof MdFab>;
